package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;import java.io.*;import java.time.*;import java.util.*;
/** Starts a real E verification job; no transport call and no caller-declared PASSED transition. */
public final class ConnectionVerificationService {
 private final EnterpriseAccess access;private final ConnectionVerificationMapper mapper;private final PermissionMapper permissions;private final ResourceReadAuthority resources;private final ModelConfigurationService models;private final ApprovedCredentialAuthority credentials;private final FormalInvocationService invocations;private final ConnectionVerificationSchema schema;private final PermissionSchema json;private final IdentityDirectoryPolicy policy;private final ConnectionVerificationPassedAuthority passed;
 public ConnectionVerificationService(EnterpriseAccess access,ConnectionVerificationMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,ModelConfigurationService models,ApprovedCredentialAuthority credentials,FormalInvocationService invocations,ConnectionVerificationSchema schema,PermissionSchema json,IdentityDirectoryPolicy policy,ConnectionVerificationPassedAuthority passed){this.access=access;this.mapper=mapper;this.permissions=permissions;this.resources=resources;this.models=models;this.credentials=credentials;this.invocations=invocations;this.schema=schema;this.json=json;this.policy=policy;this.passed=Objects.requireNonNull(passed);}
 private record Begun(ConnectionVerificationIntentProof proof,boolean fresh){}
 public JsonNode start(ApplicationSessionIdentity.Verified actor,String context,String key,byte[] body){RuntimeGovernanceSchema.key(key);var begun=access.execute(actor,a->checked(()->{
  current(a,context);JsonNode request=schema.request(body);String modelId=request.required("model_config_revision").textValue(),project=nullable(request.required("project_id"));
  var prior=mapper.byKey(Map.of("userId",a.actorId(),"key",key));if(prior.size()>1)fail();if(!prior.isEmpty()){var intent=prior.get(0);if(!a.actorId().equals(intent.actorId())||!key.equals(intent.key()))fail();if(!hash(request).equals(intent.requestHash()))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);var proof=intent(a,intent);proof.requireCurrent(a);return new Begun(proof,false);}
  var fixed=models.requireCurrentExternal(a,modelId,"MODEL_VERIFICATION",project);requireSupportedOwner(fixed,project);var model=(ModelConfigurationProtocol.Definition)fixed.definition();var credential=credentials.require(a.context().tenant_id(),model.credential_reference_id(),model.credential_revision(),model.provider(),model.base_url());
  var grant=resources.require(a,new PermissionProtocol.Scope(a.context().tenant_id(),fixed.project_id(),"CONFIGURATION",fixed.config_id()),"model.verify","MODEL_VERIFICATION");
  String id=UUID.randomUUID().toString(),operation=UUID.randomUUID().toString();var now=permissions.databaseTime();var v=new HashMap<String,Object>();v.put("userId",a.actorId());v.put("projectId",project);v.put("verificationId",id);v.put("modelRevision",modelId);v.put("configId",fixed.config_id());v.put("configurationProjectId",fixed.project_id());v.put("modelHash",hash(fixed));v.put("credentialReferenceId",model.credential_reference_id());v.put("credentialRevision",model.credential_revision());v.put("requestJson",canonical(request));v.put("requestHash",hash(request));v.put("key",key);v.put("operationId",operation);v.put("manifest",schema.manifest());v.put("classification",policy.classification());v.put("now",now);v.put("grantId",grant.grantId());v.put("grantRevision",grant.revision().toString());v.put("auditId",UUID.randomUUID().toString());v.put("eventId",UUID.randomUUID().toString());
  var intended=new ConnectionVerificationMapper.Intent(a.context().tenant_id(),project,id,a.actorId(),modelId,fixed.config_id(),hash(fixed),model.credential_reference_id(),model.credential_revision(),canonical(request),hash(request),key,operation,"1.0.0",schema.manifest(),policy.classification(),now.toInstant(ZoneOffset.UTC).toString(),grant.grantId(),grant.revision().toString(),(String)v.get("auditId"),(String)v.get("eventId"));
  var witness=intentWitness(intended);one(mapper.insertOperation(v));one(mapper.insertVerification(v));one(permissions.saveAudit(a.actorId(),project,intended.auditId(),"model.connection.requested",canonical(witness),operation,schema.manifest(),policy.classification()));one(permissions.saveEvent(a.actorId(),intended.eventId(),id,"1","model.connection.requested",canonical(witness)));one(mapper.insertIntent(v));var stored=single(mapper.intent(parameters("verificationId",id)));var proof=intent(a,stored);proof.requireCurrent(a);credential.requireCurrent();return new Begun(proof,true);
 }));
  // Explicit original POST resumes the same preparation; E never sends a provider request here.
  checked(()->invocations.startVerification(actor,context,begun.proof()));
  return bindStarted(actor,context,key,true);
 }
 public JsonNode recover(ApplicationSessionIdentity.Verified actor,String context,String key){return bindStarted(actor,context,key,false);}
 private JsonNode bindStarted(ApplicationSessionIdentity.Verified actor,String context,String key,boolean mayBind){RuntimeGovernanceSchema.key(key);return access.execute(actor,a->checked(()->{
  current(a,context);var rows=mapper.byKey(Map.of("userId",a.actorId(),"key",key));if(rows.size()>1)fail();if(rows.isEmpty())return json.object().put("schema_version","1.0.0").put("status","NOT_FOUND").putNull("receipt");var row=rows.get(0);if(!row.actorId().equals(a.actorId())||!key.equals(row.key()))fail();var proof=intent(a,row);if(mayBind)proof.requireCurrent(a);else models.requireCurrentExternal(a,row.modelRevision(),"MODEL_VERIFICATION",row.projectId());
  var completed=mapper.completed(parameters("verificationId",row.verificationId()));if(completed.size()>1)fail();if(!completed.isEmpty()){requirePassed(a,row.verificationId(),row.modelRevision(),"MODEL_VERIFICATION",row.projectId());return completionReceipt(row,completed.get(0));}
  var started=invocations.readVerificationStart(a,row.verificationId());if(started.isEmpty())return json.object().put("schema_version","1.0.0").put("status","UNKNOWN").put("verification_id",row.verificationId()).put("request_body_sha256",row.requestHash()).putNull("receipt");
  var start=started.get();var bindings=mapper.binding(parameters("verificationId",row.verificationId()));if(bindings.size()>1)fail();if(bindings.isEmpty()){
   if(!mayBind)return json.object().put("schema_version","1.0.0").put("status","UNKNOWN").put("verification_id",row.verificationId()).put("request_body_sha256",row.requestHash()).putNull("receipt");
   if(!row.verificationId().equals(start.verificationId())||!row.modelRevision().equals(start.modelRevision())||!row.requestHash().equals(start.requestBodySha256())||!row.credentialReferenceId().equals(start.credentialReferenceId())||!row.credentialRevision().equals(start.credentialRevision()))fail();
   var v=values(row);v.put("now",permissions.databaseTime());v.put("runId",start.runId());v.put("stepId",start.stepId());v.put("actionId",start.actionId());v.put("invocationId",null);v.put("inputHash",start.inputSha256());v.put("receiptJson",canonical(startReceipt(row,null)));one(mapper.insertBinding(v));one(mapper.markRunning(v));
  }
  return startReceipt(row,requireBinding(a,row));
 }));}
 private static void requireSupportedOwner(ModelConfigurationProtocol.Fixed fixed,String project){if(project==null||fixed.project_id()==null||!project.equals(fixed.project_id()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);if(!((ModelConfigurationProtocol.Definition)fixed.definition()).provider().equals("DEEPSEEK"))throw new TenantAccessException(ErrorCode.MODEL_POLICY_INCOMPLETE);}
 private static Map<String,Object> parameters(String key,Object value){return Map.of("userId",TenantScope.requireCurrent().subjectId(),key,value);}
 private static Map<String,Object> values(ConnectionVerificationMapper.Intent r){var v=new HashMap<String,Object>();v.put("userId",TenantScope.requireCurrent().subjectId());v.put("actorId",r.actorId());v.put("projectId",r.projectId());v.put("verificationId",r.verificationId());v.put("modelRevision",r.modelRevision());v.put("configId",r.configId());v.put("credentialReferenceId",r.credentialReferenceId());v.put("credentialRevision",r.credentialRevision());v.put("requestHash",r.requestHash());v.put("key",r.key());v.put("operationId",r.operationId());v.put("manifest",r.manifest());v.put("classification",r.classification());return v;}
 public ConnectionVerificationPassedAuthority.Passed requirePassed(EnterpriseAccess.Admission a,String verification,String model,String purpose,String project)throws IOException{return passed.requirePassed(a,verification,model,purpose,project);}
 public JsonNode complete(ApplicationSessionIdentity.Verified actor,String context,String key){RuntimeGovernanceSchema.key(key);return access.execute(actor,a->checked(()->{
  current(a,context);var i=single(mapper.byKey(Map.of("userId",a.actorId(),"key",key)));if(!i.actorId().equals(a.actorId())||!i.key().equals(key))fail();var proof=intent(a,i);proof.requireCurrent(a);var prior=mapper.completed(parameters("verificationId",i.verificationId()));if(prior.size()>1)fail();if(!prior.isEmpty()){requirePassed(a,i.verificationId(),i.modelRevision(),"MODEL_VERIFICATION",i.projectId());return completionReceipt(i,prior.get(0));}
  String invocation=requireBinding(a,i);if(invocation==null)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);var settled=invocations.requireCompletedVerification(a,invocation,i.verificationId());var fixed=models.requireCurrentExternal(a,i.modelRevision(),"MODEL_VERIFICATION",i.projectId());var d=(ModelConfigurationProtocol.Definition)fixed.definition();var v=values(i);v.put("invocationId",invocation);v.put("artifactJson",canonical(settled.receiptArtifact()));v.put("artifactId",settled.receiptArtifact().artifactId());v.put("receiptHash",settled.receiptSha256());v.put("priceVersion",settled.priceVersion());v.put("currency",settled.currency());v.put("settledAmount",settled.settledAmount().toString());v.put("usageReceiptId",settled.usageReceiptId());v.put("endpoint",d.base_url());v.put("verifiedAt",LocalDateTime.ofInstant(settled.verifiedAt(),ZoneOffset.UTC));v.put("now",permissions.databaseTime());v.put("auditId",UUID.randomUUID().toString());v.put("eventId",UUID.randomUUID().toString());
  var done=new ConnectionVerificationMapper.Completed(i.tenantId(),i.projectId(),i.verificationId(),invocation,(String)v.get("artifactJson"),settled.receiptSha256(),settled.priceVersion(),settled.currency(),settled.settledAmount().toString(),settled.usageReceiptId(),(String)v.get("auditId"),(String)v.get("eventId"),a.actorId(),((LocalDateTime)v.get("now")).toInstant(ZoneOffset.UTC).toString(),"1.0.0",i.manifest(),i.classification());var receipt=completionReceipt(i,done);v.put("receiptJson",canonical(receipt));
  one(permissions.saveAudit(a.actorId(),i.projectId(),done.auditId(),"model.connection.verified",canonical(completedWitness(done,receipt)),i.operationId(),i.manifest(),i.classification()));one(permissions.saveEvent(a.actorId(),done.eventId(),i.verificationId(),"3","model.connection.verified",canonical(completedWitness(done,receipt))));one(mapper.insertCompleted(v));one(mapper.markPassed(v));one(mapper.completeOperation(v));requirePassed(a,i.verificationId(),i.modelRevision(),"MODEL_VERIFICATION",i.projectId());return receipt;
 }));}
 private JsonNode completionReceipt(ConnectionVerificationMapper.Intent i,ConnectionVerificationMapper.Completed c){return passed.completionReceipt(i,c);}
 private ConnectionVerificationIntentProof intent(EnterpriseAccess.Admission a,ConnectionVerificationMapper.Intent row)throws IOException{
  var request=schema.request(row.requestJson().getBytes(java.nio.charset.StandardCharsets.UTF_8));if(!row.tenantId().equals(a.context().tenant_id())||!row.actorId().equals(a.actorId())||!"1.0.0".equals(row.schemaVersion())||!schema.manifest().equals(row.manifest())||!hash(request).equals(row.requestHash())||!row.modelRevision().equals(request.required("model_config_revision").textValue())||!Objects.equals(row.projectId(),nullable(request.required("project_id"))))fail();
  verifyLedger(row);
  return new ConnectionVerificationIntentProof(row.tenantId(),row.projectId(),row.actorId(),row.verificationId(),row.modelRevision(),row.credentialReferenceId(),row.credentialRevision(),row.requestHash(),row.operationId(),row.key(),request,now->{
   if(!now.actorId().equals(row.actorId())||!now.context().tenant_id().equals(row.tenantId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
   var persisted=single(mapper.intent(parameters("verificationId",row.verificationId())));if(!persisted.equals(row))fail();verifyLedger(persisted);
   var fixed=models.requireCurrentExternal(now,row.modelRevision(),"MODEL_VERIFICATION",row.projectId());requireSupportedOwner(fixed,row.projectId());var definition=(ModelConfigurationProtocol.Definition)fixed.definition();if(!hash(fixed).equals(row.modelHash())||!fixed.config_id().equals(row.configId())||!definition.credential_reference_id().equals(row.credentialReferenceId())||!definition.credential_revision().equals(row.credentialRevision()))fail();
   credentials.require(row.tenantId(),row.credentialReferenceId(),row.credentialRevision(),definition.provider(),definition.base_url()).requireCurrent();var grant=resources.require(now,new PermissionProtocol.Scope(row.tenantId(),fixed.project_id(),"CONFIGURATION",fixed.config_id()),"model.verify","MODEL_VERIFICATION");if(!grant.grantId().equals(row.grantId())||!grant.revision().toString().equals(row.grantRevision()))throw new TenantAccessException(ErrorCode.SCOPE_STALE);
  });
 }
 private String requireBinding(EnterpriseAccess.Admission a,ConnectionVerificationMapper.Intent intent)throws IOException{return requireBinding(a,intent,true);}
 private String requireBinding(EnterpriseAccess.Admission a,ConnectionVerificationMapper.Intent intent,boolean ownerOnly)throws IOException{return passed.requireBinding(a,intent,ownerOnly);}
 private JsonNode intentWitness(ConnectionVerificationMapper.Intent i)throws IOException{return passed.intentWitness(i);}
 private JsonNode completedWitness(ConnectionVerificationMapper.Completed c,JsonNode receipt)throws IOException{return passed.completedWitness(c,receipt);}
 private void verifyLedger(ConnectionVerificationMapper.Intent intent)throws IOException{passed.verifyLedger(intent);}
 private JsonNode startReceipt(ConnectionVerificationMapper.Intent i,String invocation){var n=json.object();n.put("schema_version","1.0.0");n.put("verification_id",i.verificationId());n.put("operation_id",i.operationId());n.put("invocation_id",invocation);n.put("request_body_sha256",i.requestHash());n.put("status","RUNNING");return n;}
 private JsonNode schemaRead(String value)throws IOException{return schema.read(value);}
 private String canonical(Object value)throws IOException{return new String(ContentReadAuthorization.canonicalBytes(value),java.nio.charset.StandardCharsets.UTF_8);}private String hash(Object value)throws IOException{return org.apache.commons.codec.digest.DigestUtils.sha256Hex(ContentReadAuthorization.canonicalBytes(value));}
 private static String nullable(JsonNode n){return n.isNull()?null:n.textValue();}private static void current(EnterpriseAccess.Admission a,String c){if(!a.context().context_revision().equals(c))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}private static void one(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static <T>T single(List<T> rows){if(rows.size()!=1)fail();return Objects.requireNonNull(rows.get(0));}private static void fail(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private interface Work<T>{T run()throws IOException;}private static <T>T checked(Work<T> work){try{return work.run();}catch(IOException e){throw new SchemaRejection(ErrorCode.CONTENT_MISMATCH);}}
}
